'use strict';
const {readFileSync, writeFileSync} = require('node:fs');
const {createHash} = require('node:crypto');
const path = require('node:path');
const dirname = path.resolve('benchmarks/frameworks');
const config = require(path.join(dirname,'package.json'));
const esbuild = require(path.join(dirname, 'node_modules/esbuild'));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const opts = {
  absWorkingDir:dirname, bundle:true, minify:true, format:'esm', platform:'browser',
  conditions:['browser','production'], target:'es2022', jsx:'automatic',
  define:{'process.env.NODE_ENV':'"production"'}, metafile:true, write:false,
};
const stock = esbuild.buildSync({...opts, entryPoints:['rich/scale-react.jsx'], outfile:path.join(dirname,'dist/scale/react.js')});
const stockSum = sha(stock.outputFiles[0].contents);
const stockManifest = require(path.join(dirname,'dist/scale/manifest.json'));
if (stockSum !== stockManifest.bundles.react.sha256) throw Error('Build settings drifted');
const source = readFileSync(path.join(__dirname,'scale-react-slots.jsx'),'utf8');
const result = esbuild.buildSync({...opts, stdin:{contents:source, loader:'jsx', sourcefile:'scale-react-slots.jsx',
  resolveDir:__dirname},nodePaths:[path.join(dirname,'node_modules')], outfile:path.join(__dirname, 'react-slots.mjs')});
if(result.outputFiles.length !== 1 || Object.values(result.metafile.outputs)[0].imports.length) throw Error('Expected one self-contained module');
writeFileSync(path.join(__dirname,'react-slots.mjs'), result.outputFiles[0].contents);
const metadata = {
  cwd:'Saba checkout root', replay:'node /path/to/build.cjs (place scale-react-slots.jsx and pool.mjs beside build.cjs)',
  react:config.dependencies.react, reactDOM:config.dependencies['react-dom'], esbuild:esbuild.version,
  settings:opts, stockBundleSha256:stockSum, sourceSha256:sha(source), poolSha256:sha(readFileSync(path.join(__dirname,'pool.mjs'))),
  bundleSha256:sha(result.outputFiles[0].contents), bytes:result.outputFiles[0].contents.length,
};
writeFileSync(path.join(__dirname,'build.json'), JSON.stringify(metadata,null,2)+'\n');
console.log(JSON.stringify(metadata));

