const path = require('node:path');
const assert = require('node:assert/strict');
const {execFileSync} = require('node:child_process');
const fs = require('node:fs');
const {createHash} = require('node:crypto');
const root = process.cwd();
const framework = path.join(root, 'benchmarks/frameworks');
const esbuild = require(path.join(framework, 'node_modules/esbuild'));
const jsx = path.join(__dirname, 'scale-saba-slots.jsx');
const generated = path.join(__dirname, 'scale-saba-slots.generated.mjs');
const output = path.join(__dirname, 'saba-slots.mjs');
const runtime = path.join(root, 'src/modules/dom.js');
const args = ['run', path.join(framework, 'operations/compile'), '-collection:shared=' + process.env.WEBTOOLS_SHARED, '-out:' + path.join(__dirname, 'saba-jsx-compiler'), '--', jsx, generated];
assert.ok(process.env.WEBTOOLS_SHARED, 'Set WEBTOOLS_SHARED to the frozen Saba dependency collection');
execFileSync(process.env.ODIN || 'odin',args,{stdio:'inherit'});
async function main() {
  const result = await esbuild.build({absWorkingDir: framework, entryPoints: [generated], outfile:output,
    bundle:true, minify:true, format:'esm', platform:'browser', conditions:['browser','production'],
    target:'es2022', jsx:'automatic', define:{'process.env.NODE_ENV':'"production"'}, metafile:true,
    plugins:[{name:'saba-runtime',setup(builder) {
      builder.onResolve({filter:/^\/__saba\/dom\.js$/}, () => ({path:runtime}));
    }}]});
  const outputs = Object.values(result.metafile.outputs);
  assert.equal(outputs.length,1); assert.equal(outputs[0].imports.length,0);
  const files=[jsx,generated,path.join(__dirname,'pool.mjs'),runtime,output];
  const metadata=files.map(file=>({name:path.basename(file),sha256:createHash('sha256').update(fs.readFileSync(file)).digest('hex')}));
  fs.writeFileSync(path.join(__dirname,'saba-build.json'),JSON.stringify({esbuild:esbuild.version,metadata},null,2)+'\n');
}
main().catch(e=>{console.error(e);process.exitCode=1;});

