import {createSlotPool} from './pool.mjs';
import { memo } from 'react';
import { flushSync } from 'react-dom';
import { createRoot } from 'react-dom/client';

const Tile = memo(function Tile({record}) {
  return <div className="cell" data-id={record.id}>{record.id + ' · ' + record.score}</div>;
});

function Band({records, slots}) {
  return records.map((record, i) => <Tile key={slots[i]} record={record}/>);
}

export function mountScaleBand(host, initialRecords) {
  const root = createRoot(host);
  const assign = createSlotPool();
  const replace = records => {
    const slots = assign(records[0]?.id ?? 0, records.length);
    flushSync(() => root.render(<Band records={records} slots={slots}/>));
  };
  replace(initialRecords);
  return {replace, dispose:() => root.unmount()};
}

