import { keyed, mount, signal } from '/__saba/dom.js';
import { createSlotPool } from './pool.mjs';

function Tile(record) {
  return <div class="cell" data-id={record().id}>{record().id + ' · ' + record().score}</div>;
}

export function mountScaleBand(host, initialRecords) {
  const assign = createSlotPool();
  let first = initialRecords[0]?.id ?? 0;
  let slots = assign(first, initialRecords.length);
  const records = signal(initialRecords);
  const rows = keyed(records, record => slots[record.id - first], Tile);
  const dispose = mount(host, () => <>{rows}</>);
  function replace(next) {
    first = next[0]?.id ?? 0;
    slots = assign(first, next.length);
    records.set(next);
  }
  return { replace, dispose };
}

