// Slot numbers identify mounted Tile instances. Consecutive IDs are a property
// of this grid. Preserve overlapping IDs' slots when the window changes.
export function createSlotPool() {
  let first = 0, slots = [], serial = 0;
  return function assign(nextFirst, size) {
    const sharedFirst = Math.max(first, nextFirst);
    const sharedEnd = Math.min(first + slots.length, nextFirst + size);
    if (size === slots.length && (first === nextFirst || sharedFirst >= sharedEnd)) {
      first = nextFirst;
      return slots;
    }
    let next;
    if (sharedFirst >= sharedEnd) {
      next = slots.slice(0, size);
      while (next.length < size) next.push(serial++);
    } else {
      const start = sharedFirst - first, end = sharedEnd - first;
      const free = slots.slice(0, start).concat(slots.slice(end));
      let freeIndex = 0;
      next = new Array(size);
      for (let i = 0; i < size; i++) {
        const id = nextFirst + i;
        if (id >= sharedFirst && id < sharedEnd) next[i] = slots[id - first];
        else next[i] = freeIndex < free.length ? free[freeIndex++] : serial++;
      }
    }
    first = nextFirst;
    slots = next;
    return slots;
  };
}

