'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const crypto = require('node:crypto');
const {chromium} = require(process.env.PLAYWRIGHT_PATH || 'playwright');
const [manifestPath, output] = process.argv.slice(2);
assert.ok(manifestPath && output, 'Usage: node audit-mutations.cjs MANIFEST.json OUT.json (run from Saba checkout)');
const hash = buffer => crypto.createHash('sha256').update(buffer).digest('hex');

async function auditPage({name, identity}) {
  const {mountScaleBand} = await import('/renderer.mjs');
  const check = (condition, description) => { if (!condition) throw new Error(name + ': ' + description); };
  const original = id => ({id, group:id % 23, score:(id * 37 + (id % 23) * 13) % 1000});
  const model = new Map();
  function windowRecords(first, size) {
    return Array.from({length:size}, (_, offset) => {
      const id = first + offset;
      if (!model.has(id)) model.set(id, original(id));
      return model.get(id);
    });
  }
  function snapshot(host, records) {
    const elements = [...host.children];
    const texts = elements.map(e => e.firstChild);
    check(elements.length === records.length, 'incorrect cell count');
    records.forEach((record,i) => {
      const el = elements[i], text = texts[i];
      check(el.tagName === 'DIV' && el.className === 'cell' && el.getAttribute('data-id') === String(record.id) &&
        el.childNodes.length === 1 && text?.nodeType === Node.TEXT_NODE &&
        text.data === record.id + ' · ' + record.score && el.isConnected, 'incorrect cell for ' + record.id);
    });
    return {elements, texts};
  }
  function inspect(host, renderer, oldRows, nextRows) {
    const before = snapshot(host,oldRows);
    const oldElements = new Set(before.elements), oldTexts = new Set(before.texts);
    const observer = new MutationObserver(() => {});
    observer.observe(host,{subtree:true,childList:true,attributes:true,characterData:true});
    let mutations;
    try {
      renderer.replace(nextRows);
      mutations = observer.takeRecords();
    } finally { observer.disconnect(); }
    const after = snapshot(host,nextRows);
    const stillInBand = new Set(after.elements), textsInBand = new Set(after.texts);
    const priorKey = new Map(oldRows.map((r,i) => [r.id,i]));
    let retainedKeys = 0;
    nextRows.forEach((r,i) => {
      const oldIndex = priorKey.get(r.id);
      if (oldIndex === undefined) return;
      retainedKeys++;
      check(after.elements[i] === before.elements[oldIndex] && after.texts[i] === before.texts[oldIndex],
        'overlapping key lost its element or text');
    });
    const oldElementsReused = before.elements.filter(el => stillInBand.has(el)).length;
    const oldTextsReused = before.texts.filter(text => textsInBand.has(text)).length;
    const expected = identity === 'slots' ? Math.min(oldRows.length,nextRows.length) : retainedKeys;
    check(oldElementsReused === expected && oldTextsReused === expected, 'wrong total reused for ' + identity);
    const counts = {
      directElementAdds:0, directElementRemovals:0, directAddsPreviouslyInBand:0, directRemovalsEndingInBand:0,
      descendantChildListRecords:0, attributes:{}, attributesOnPreviousCells:{},
      characterDataWrites:0, characterDataWritesOnPreviousText:0,
    };
    const increment = (object,key) => object[key] = (object[key] || 0) + 1;
    for (const m of mutations) {
      if (m.type === 'childList' && m.target === host) {
        for (const el of m.addedNodes) if (el.nodeType === Node.ELEMENT_NODE) {
          counts.directElementAdds++; if (oldElements.has(el)) counts.directAddsPreviouslyInBand++;
        }
        for (const el of m.removedNodes) if (el.nodeType === Node.ELEMENT_NODE) {
          counts.directElementRemovals++; if (stillInBand.has(el)) counts.directRemovalsEndingInBand++;
        }
      } else if (m.type === 'childList') counts.descendantChildListRecords++;
      else if (m.type === 'attributes') {
        increment(counts.attributes,m.attributeName);
        if (oldElements.has(m.target)) increment(counts.attributesOnPreviousCells,m.attributeName);
      } else if (m.type === 'characterData') {
        counts.characterDataWrites++;
        if (oldTexts.has(m.target)) counts.characterDataWritesOnPreviousText++;
      }
    }
    return {fromFirst:oldRows[0].id,toFirst:nextRows[0].id,windowSize:after.elements.length,retainedKeys,
      oldElementsReused,oldTextsReused,firstCell:after.elements[0].outerHTML,lastCell:after.elements.at(-1).outerHTML,counts};
  }
  function makeBand() {
    const el = document.createElement('div');
    el.className = 'band';
    document.body.appendChild(el);
    return el;
  }
  const start = windowRecords(0,192), final = windowRecords(999808,192);
  const changed = r => r.id % 97 === 0 || r.id === 999999 ? {...r,score:r.score+7} : r;
  const updated = start.map(changed), destination = final.map(changed);
  const jumpHost = makeBand(), jumpBand = mountScaleBand(jumpHost,start);
  let jump;
  try {
    jumpBand.replace(updated);
    jump = inspect(jumpHost,jumpBand,updated,destination);
  } finally {jumpBand.dispose(); jumpHost.remove();}
  const left = windowRecords(0,256), right = windowRecords(64,256);
  const scrollHost = makeBand(), scrollBand = mountScaleBand(scrollHost,left);
  try {
    const forward = inspect(scrollHost,scrollBand,left,right);
    const backward = inspect(scrollHost,scrollBand,right,left);
    return {jump,forward,backward};
  } finally {scrollBand.dispose(); scrollHost.remove();}
}

async function main() {
  const manifestBytes = await fs.readFile(manifestPath);
  const manifest = JSON.parse(manifestBytes);
  const browser = await chromium.launch({channel:'chromium',executablePath:process.env.SABA_CHROME});
  try {
    const report = {metadata:{scriptSha256:hash(await fs.readFile(__filename)),manifestSha256:hash(manifestBytes),
      chromium:browser.version(),arms:{},method:'Untimed synchronous replace on a connected band. MutationObserver counts modifications within the observed band, not detached node construction. Direct add/removal includes reordering an existing child; separate counts identify moves. Start, sparse update and disposal are outside the observer. Each arm gets a fresh page.'},results:{}};
    for (const [name,spec] of Object.entries(manifest)) {
      assert.ok(['keyed','slots'].includes(spec.identity));
      const bytes = await fs.readFile(spec.path);
      report.metadata.arms[name] = {...spec,sha256:hash(bytes)};
      const page = await browser.newPage({serviceWorkers:'block'});
      try {
        const errors=[];
        page.on('pageerror',error=>errors.push(error.message));
        await page.route('http://saba-audit.test/**',async route => {
          const p = new URL(route.request().url()).pathname;
          if (p === '/') return route.fulfill({status:200,contentType:'text/html',body:'<!doctype html><body></body>'});
          if (p === '/renderer.mjs') return route.fulfill({status:200,contentType:'text/javascript',body:bytes});
          return route.fulfill({status:404,body:''});
        });
        await page.goto('http://saba-audit.test/');
        report.results[name] = await page.evaluate(auditPage,{name,identity:spec.identity});
        assert.deepEqual(errors,[]);
      } finally {await page.close();}
    }
    await fs.writeFile(output,JSON.stringify(report,null,2)+'\n');
  } finally {await browser.close();}
}
main().catch(err=>{console.error(err);process.exitCode=1;});
